package com.andye.warmod.radar.client.gui;
import com.andye.warmod.radar.client.*;import java.util.*;import net.minecraft.client.gui.Font;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.network.chat.Component;import net.minecraft.world.phys.Vec3;
public final class RadarSidebar{private RadarSidebar(){}public static void render(GuiGraphicsExtractor g,Font font,ClientRadarState state,double now,int left,int top,int width,int height,int scroll){g.fill(left,top,left+width,top+height,0xee10171b);g.enableScissor(left,top,left+width,top+height);int y=top+8-scroll;g.text(font,Component.literal("TRACKS"),left+8,y,0xffffffff);y+=14;for(ClientRadarTrack track:state.tracks()){boolean selected=track.id().equals(state.selectedTrackId());if(selected)g.fill(left+5,y-2,left+width-5,y+11,0xff34444c);String id=track.id().toString().substring(0,8);g.text(font,Component.literal(id+"  "+track.snapshot().phase().label()),left+8,y,selected?0xffffffff:0xffd5b06a);y+=14;}ClientRadarTrack selected=state.selected();if(selected!=null){y+=5;var s=selected.snapshot();Vec3 p=selected.position(now),v=selected.velocity(now),target=selected.target();double distance=p.distanceTo(target);line(g,font,"TRACK",s.trackId().toString().substring(0,8),left,y);y+=20;line(g,font,"LAUNCHED BY",s.ownerDisplayName(),left,y);y+=20;line(g,font,"PAYLOAD",s.payloadType().name(),left,y);y+=20;line(g,font,"STAGE",s.phase().label(),left,y);y+=20;line(g,font,"POSITION",format(p),left,y);y+=20;line(g,font,"ALTITUDE",String.format(Locale.ROOT,"%.0f | %+,.0f above target",p.y,p.y-target.y),left,y);y+=20;line(g,font,"SPEED",String.format(Locale.ROOT,"%.1f blocks/s",v.length()*20),left,y);y+=20;line(g,font,"H / V SPEED",String.format(Locale.ROOT,"%.1f / %+.1f blocks/s",v.horizontalDistance()*20,v.y*20),left,y);y+=20;line(g,font,"TARGET",format(target),left,y);y+=20;line(g,font,"DISTANCE",String.format(Locale.ROOT,"%.0f blocks",distance),left,y);y+=20;double eta=s.terminalPlan().map(t->Math.max(0,t.flightTicks()-(now-t.launchGameTime()))/20).orElseGet(()->s.carrierPlan().map(c->Math.max(0,c.ignitionTicks()+c.boostTicks()+c.coastTicks()-(now-c.launchGameTime()))/20).orElse(0.0));line(g,font,"ETA",String.format(Locale.ROOT,"%.1f seconds",eta),left,y);}g.disableScissor();}private static void line(GuiGraphicsExtractor g,Font f,String label,String value,int x,int y){g.text(f,Component.literal(label),x+8,y,0xff7e99a5);g.text(f,Component.literal(value),x+8,y+9,0xffffffff);}private static String format(Vec3 p){return String.format(Locale.ROOT,"%.0f / %.0f / %.0f",p.x,p.y,p.z);}}
